import { useCEProductCustomization } from '../../bitf-customization-engine/useCEProductCustomization.jsx';
import { useEffect, useMemo, useState } from 'react';
import { useTranslate } from '../../hooks/useTranslate.jsx';

export function CEProductCustomizationForm({ customizationHookConfig }) {
  const { store, setStore, toggleAddOn } = useCEProductCustomization(customizationHookConfig);
  const { translate } = useTranslate(customizationHookConfig.language);

  const {
    allCustomizationTypes,
    allCustomizations,
    allAddOns,
    filteredPlayers,
    currentPlayer,
    currentAddOns,
    currentCustomizationType,
    currentCustomizationProduct,
    currentFont,
    customizationName,
    customizationNumber,
    customizationEngineSettings,
    currentFormValidator,
  } = store;

  const [displayPrice, setDisplayPrice] = useState(null);
  const [maxNameLength, setMaxNameLength] = useState(null);
  const [maxNumberLength, setMaxNumberLength] = useState(null);

  // Update validation limits when currentFormValidator or customizationEngineSettings change
  useEffect(() => {
    const nameLength = currentFormValidator?.maxNameChars ?? customizationEngineSettings?.defaultMaxNameChars;
    const numberLength = currentFormValidator?.maxNumberChars ?? customizationEngineSettings?.defaultMaxNumberChars;

    setMaxNameLength(nameLength);
    setMaxNumberLength(numberLength);
  }, [currentFormValidator, customizationEngineSettings]);
  const allowedNameCharactersSet = useMemo(() => {
    if (!currentFont?.chars) {
      return null;
    }
    return new Set(currentFont.chars.split(''));
  }, [currentFont]);

  useEffect(() => {
    let priceData = null;

    if (currentCustomizationProduct?.selectedOrFirstAvailableVariant?.price) {
      const { amount, currencyCode } = currentCustomizationProduct.selectedOrFirstAvailableVariant.price;
      priceData = { amount, currencyCode };
    } else if (currentCustomizationType && allCustomizations) {
      const customizationsForType = allCustomizations.filter(
        (customization) => customization.value.customizationType === currentCustomizationType,
      );
      if (customizationsForType.length > 0 && customizationsForType[0].value.selectedOrFirstAvailableVariant?.price) {
        const { amount, currencyCode } = customizationsForType[0].value.selectedOrFirstAvailableVariant.price;
        priceData = { amount, currencyCode };
      }
    }

    setDisplayPrice(priceData);
  }, [currentCustomizationProduct, currentCustomizationType, allCustomizations]);

  const formatPrice = (priceData) => {
    if (!priceData) return '';

    const { amount, currencyCode } = priceData;
    const numericAmount = parseFloat(amount);

    if (numericAmount <= 0) return translate('customization.form.free');

    try {
      return new Intl.NumberFormat('it-IT', {
        style: 'currency',
        currency: currencyCode,
      }).format(numericAmount);
    } catch (error) {
      // Fallback se la valuta non è supportata
      return `${amount} ${currencyCode}`;
    }
  };

  return (
    <div className="product-customization__form-container">
      {allCustomizationTypes && allCustomizationTypes.length > 0 ? (
        <div>
          <div className="product-customization__form-section-title">
            <p className="Body Medium Uppercase">
              {translate('customization.form.customize')} {formatPrice(displayPrice)}
            </p>
          </div>
          <div className="product-customization__form-buttons">
            <button
              onClick={() =>
                setStore({
                  currentCustomizationType: null,
                  currentPlayer: null,
                  customizationName: '',
                  customizationNumber: '',
                  currentCustomizationProduct: null,
                })
              }
              className={`customization-button deselect ${currentCustomizationType === null ? 'active Medium' : ''}`}
              title={translate('customization.form.deselect')}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="2" />
                <path d="m4.93 4.93 14.14 14.14" stroke="currentColor" strokeWidth="2" />
              </svg>
            </button>
            {allCustomizationTypes && allCustomizationTypes.length > 0 ? (
              allCustomizationTypes.map((customizationType) => (
                <button
                  key={customizationType.value}
                  className={`customization-button ${customizationType.value === currentCustomizationType ? 'active Medium' : ''}`}
                  size="sm"
                  onClick={() => setStore({ currentCustomizationType: customizationType.value })}
                >
                  <div>{translate(`customization.form.${customizationType.value}`)}</div>
                </button>
              ))
            ) : (
              <></>
            )}
          </div>
        </div>
      ) : (
        <></>
      )}

      {currentCustomizationType === 'player' && (
        <div>
          <div className="product-customization__form-section-title">
            <p className="Body Medium Uppercase">{translate('customization.form.choose_player')}</p>
          </div>
          <div className="product-customization__form-section-players">
            {filteredPlayers ? (
              <select
                className="select Body Medium Capitalize"
                value={currentPlayer?.id || ''}
                onChange={(e) => {
                  if (e.target.value === 'null' || e.target.value === '') {
                    setStore({ currentPlayer: null });
                  } else {
                    const selectedPlayer = filteredPlayers.find((player) => player.id === e.target.value);
                    setStore({ currentPlayer: selectedPlayer || null });
                  }
                }}
              >
                <option value="null">{translate('customization.form.player_name')}</option>
                {filteredPlayers.map((player) => (
                  <option key={player.id} value={player.id}>
                    {player.number} - {player.label}
                  </option>
                ))}
              </select>
            ) : (
              <div>{translate('customization.form.no_players_found')}</div>
            )}
          </div>
        </div>
      )}
      {(currentCustomizationType === 'name' ||
        currentCustomizationType === 'number' ||
        currentCustomizationType === 'name_and_number') && (
        <div className="product-customization__form-section-name-number">
          {(currentCustomizationType === 'name' || currentCustomizationType === 'name_and_number') && (
            <label>
              <input
                type="text"
                placeholder={translate('customization.form.name')}
                value={customizationName}
                maxLength={maxNameLength ?? undefined}
                onChange={(e) => {
                  const rawValue = e.target.value.toUpperCase();
                  let sanitizedValue = rawValue;
                  if (allowedNameCharactersSet) {
                    sanitizedValue = rawValue
                      .split('')
                      .filter((char) => allowedNameCharactersSet.has(char))
                      .join('');
                  }
                  if (maxNameLength) {
                    sanitizedValue = sanitizedValue.slice(0, maxNameLength);
                  }
                  setStore({ customizationName: sanitizedValue });
                }}
                className="input"
              />
              {maxNameLength && (
                <div className="ExtraSmall" style={{ marginTop: '4px', color: '#666' }}>
                  {translate('customization.form.max_characters', { max_chars: maxNameLength })}
                </div>
              )}
            </label>
          )}
          <div className="d-flex gap-2">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="24"
              height="16"
              class="{{ class | strip }}"
              viewBox="0 0 24 24"
            >
              <g id="Raggruppa_13665" data-name="Raggruppa 13665" transform="translate(0 -1.263)">
                <g
                  id="Ellisse_1263"
                  data-name="Ellisse 1263"
                  transform="translate(0 1.263)"
                  fill="none"
                  stroke="currentColor"
                  stroke-width="1"
                >
                  <circle cx="12" cy="12" r="12" stroke="none" />
                  <circle cx="12" cy="12" r="11.5" fill="none" />
                </g>
                <text
                  id="i"
                  transform="translate(10 20.263)"
                  font-size="20"
                  font-family="HelveticaNeue, Helvetica Neue"
                >
                  <tspan x="0" y="0">
                    i
                  </tspan>
                </text>
              </g>
            </svg>
            <p className="ExtraSmall">{translate('customization.form.name_and_number_info_label')}</p>
          </div>
          {(currentCustomizationType === 'number' || currentCustomizationType === 'name_and_number') && (
            <label>
              <input
                type="text"
                placeholder={translate('customization.form.number')}
                value={customizationNumber}
                inputMode="numeric"
                pattern="[0-9]*"
                maxLength={maxNumberLength ?? undefined}
                onChange={(e) => {
                  const digitsOnly = e.target.value.replace(/\D/g, '');
                  const sanitizedNumber = maxNumberLength ? digitsOnly.slice(0, maxNumberLength) : digitsOnly;
                  setStore({ customizationNumber: sanitizedNumber });
                }}
                className="input"
              />
              {maxNumberLength && (
                <div className="ExtraSmall" style={{ marginTop: '4px', color: '#666' }}>
                  {translate('customization.form.max_number_characters', { max_chars: maxNumberLength })}
                </div>
              )}
            </label>
          )}
        </div>
      )}

      <div className="product-customization__form-section-addons">
        {allAddOns &&
          (() => {
            // Raggruppa gli add-ons per customizationAddOnType
            const groupedAddOns = allAddOns.reduce((groups, addOn) => {
              const type = addOn.value.customizationAddOnType || 'other';
              if (!groups[type]) {
                groups[type] = [];
              }
              groups[type].push(addOn);
              return groups;
            }, {});

            return Object.entries(groupedAddOns).map(([addOnType, addOns]) => {
              // Trova l'add-on selezionato per questo tipo
              const selectedAddOn = addOns.find((addOn) => currentAddOns?.includes(addOn.value));

              return (
                <div key={addOnType}>
                  <div className="product-customization__form-section-title">
                    <p className="Body Medium Uppercase">
                      {translate(`customization.form.${addOnType}`)}
                      {selectedAddOn && (
                        <span className="Body Medium">
                          {formatPrice({
                            amount: selectedAddOn.value.selectedOrFirstAvailableVariant.price.amount,
                            currencyCode: selectedAddOn.value.selectedOrFirstAvailableVariant.price.currencyCode,
                          })}
                        </span>
                      )}
                    </p>
                  </div>
                  <div className="product-customization__form-buttons">
                    <button
                      onClick={() => {
                        setStore({
                          currentAddOns: currentAddOns.filter((a) => {
                            return !addOns.map((addOn) => addOn.value.id).includes(a.id);
                          }),
                        });
                      }}
                      className={`customization-button deselect ${!selectedAddOn ? 'active Medium' : ''}`}
                      title={translate('customization.form.deselect')}
                      disabled={addOns.every((addOn) => addOn.value.customizationAddOnRequired)}
                    >
                      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="2" />
                        <path d="m4.93 4.93 14.14 14.14" stroke="currentColor" strokeWidth="2" />
                      </svg>
                    </button>
                    {addOns.map((addOn) => (
                      <button
                        onClick={() => {
                          toggleAddOn(addOn.value);
                        }}
                        className={`customization-button ${currentAddOns?.find((selectedAddOn) => selectedAddOn.id === addOn.value.id) ? 'active Medium' : ''}`}
                        key={addOn.value.id}
                        hidden={addOn.hidden}
                      >
                        {addOn.value?.images[0]?.url && (
                          <img
                            src={addOn.value.images[0].url}
                            alt={addOn.value.images[0].altText || addOn.value.customizationLabel}
                            className="customization-button__image"
                          />
                        )}
                        {addOn.value.customizationLabel}
                      </button>
                    ))}
                  </div>
                </div>
              );
            });
          })()}
      </div>
      <div className="d-flex gap-2">
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="16" class="{{ class | strip }}" viewBox="0 0 24 24">
          <g id="Raggruppa_13665" data-name="Raggruppa 13665" transform="translate(0 -1.263)">
            <g
              id="Ellisse_1263"
              data-name="Ellisse 1263"
              transform="translate(0 1.263)"
              fill="none"
              stroke="currentColor"
              stroke-width="1"
            >
              <circle cx="12" cy="12" r="12" stroke="none" />
              <circle cx="12" cy="12" r="11.5" fill="none" />
            </g>
            <text id="i" transform="translate(10 20.263)" font-size="20" font-family="HelveticaNeue, Helvetica Neue">
              <tspan x="0" y="0">
                i
              </tspan>
            </text>
          </g>
        </svg>
        <p className="ExtraSmall">{translate('customization.form.customization_info')}</p>
      </div>
    </div>
  );
}
